-- The conservation law (S-0033/tests-rfc-0009-amendment) as a runtime audit: every bronze row
-- lands in exactly one of the entity, an unresolved reject, or the deduped
-- count. Blocking — a row in neither side of the split has been silently
-- dropped, which is the failure this package exists to make impossible.
AUDIT (
  name order_line_conservation
);

WITH _survivors AS (
  SELECT
    *
  FROM (
    SELECT
      SAFE_CAST(JSON_EXTRACT_SCALAR(properties, '$.gift_note') AS STRING) AS gift_note,
      SAFE_CAST(position AS INT64) AS line_no,
      SAFE_CAST(JSON_EXTRACT_SCALAR(`order`, '$.id') AS STRING) AS order_id,
      SAFE_CAST(CASE
        WHEN SUBSTR(CAST(created_at AS STRING), 11) LIKE '%+%'
        OR SUBSTR(CAST(created_at AS STRING), 11) LIKE '%-%'
        THEN NULL
        ELSE REPLACE(REPLACE(CAST(created_at AS STRING), 'T', ' '), 't', ' ')
      END AS DATETIME) AS placed_at,
      SAFE_CAST(quantity AS INT64) AS quantity,
      SAFE_CAST(JSON_EXTRACT_SCALAR(variant, '$.sku') AS STRING) AS sku,
      CASE SAFE_CAST(financial_status AS STRING)
        WHEN 'pending'
        THEN 'open'
        WHEN 'paid'
        THEN 'closed'
        WHEN 'refunded'
        THEN 'reversed'
        ELSE SAFE_CAST(financial_status AS STRING)
      END AS status,
      _ingested_at,
      _load_id,
      _source_row_id,
      SAFE_CAST(JSON_EXTRACT_SCALAR(properties, '$.gift_note') AS STRING) IS NULL
      AND (
        NOT JSON_EXTRACT_SCALAR(properties, '$.gift_note') IS NULL
      ) AS _branch_gift_note_coercible,
      SAFE_CAST(position AS INT64) IS NULL AND (
        NOT position IS NULL
      ) AS _branch_line_no_coercible,
      SAFE_CAST(JSON_EXTRACT_SCALAR(`order`, '$.id') AS STRING) IS NULL
      AND (
        NOT JSON_EXTRACT_SCALAR(`order`, '$.id') IS NULL
      ) AS _branch_order_id_coercible,
      SAFE_CAST(CASE
        WHEN SUBSTR(CAST(created_at AS STRING), 11) LIKE '%+%'
        OR SUBSTR(CAST(created_at AS STRING), 11) LIKE '%-%'
        THEN NULL
        ELSE REPLACE(REPLACE(CAST(created_at AS STRING), 'T', ' '), 't', ' ')
      END AS DATETIME) IS NULL
      AND (
        NOT created_at IS NULL
      ) AS _branch_placed_at_coercible,
      SAFE_CAST(quantity AS INT64) IS NULL AND (
        NOT quantity IS NULL
      ) AS _branch_quantity_coercible,
      SAFE_CAST(JSON_EXTRACT_SCALAR(variant, '$.sku') AS STRING) IS NULL
      AND (
        NOT JSON_EXTRACT_SCALAR(variant, '$.sku') IS NULL
      ) AS _branch_sku_coercible,
      CASE SAFE_CAST(financial_status AS STRING)
        WHEN 'pending'
        THEN 'open'
        WHEN 'paid'
        THEN 'closed'
        WHEN 'refunded'
        THEN 'reversed'
        ELSE SAFE_CAST(financial_status AS STRING)
      END IS NULL
      AND (
        NOT financial_status IS NULL
      ) AS _branch_status_coercible,
      NOT CASE SAFE_CAST(financial_status AS STRING)
        WHEN 'pending'
        THEN 'open'
        WHEN 'paid'
        THEN 'closed'
        WHEN 'refunded'
        THEN 'reversed'
        ELSE SAFE_CAST(financial_status AS STRING)
      END IN ('closed', 'open', 'reversed') AS _branch_status_in_enum,
      'shopify__order_lines' AS _source
    FROM bronze.shopify__order_lines
    UNION ALL
    SELECT
      CAST(NULL AS STRING) AS gift_note,
      SAFE_CAST(item_index AS INT64) AS line_no,
      SAFE_CAST(order_number AS STRING) AS order_id,
      SAFE_CAST(CASE
        WHEN SUBSTR(CAST(created AS STRING), 11) LIKE '%+%'
        OR SUBSTR(CAST(created AS STRING), 11) LIKE '%-%'
        THEN NULL
        ELSE REPLACE(REPLACE(CAST(created AS STRING), 'T', ' '), 't', ' ')
      END AS DATETIME) AS placed_at,
      SAFE_CAST(qty AS INT64) AS quantity,
      SAFE_CAST(product_sku AS STRING) AS sku,
      CASE SAFE_CAST(state AS STRING)
        WHEN 'PROCESSING'
        THEN 'open'
        WHEN 'COMPLETE'
        THEN 'closed'
        ELSE SAFE_CAST(state AS STRING)
      END AS status,
      _ingested_at,
      _load_id,
      _source_row_id,
      FALSE AS _branch_gift_note_coercible,
      SAFE_CAST(item_index AS INT64) IS NULL AND (
        NOT item_index IS NULL
      ) AS _branch_line_no_coercible,
      SAFE_CAST(order_number AS STRING) IS NULL AND (
        NOT order_number IS NULL
      ) AS _branch_order_id_coercible,
      SAFE_CAST(CASE
        WHEN SUBSTR(CAST(created AS STRING), 11) LIKE '%+%'
        OR SUBSTR(CAST(created AS STRING), 11) LIKE '%-%'
        THEN NULL
        ELSE REPLACE(REPLACE(CAST(created AS STRING), 'T', ' '), 't', ' ')
      END AS DATETIME) IS NULL
      AND (
        NOT created IS NULL
      ) AS _branch_placed_at_coercible,
      SAFE_CAST(qty AS INT64) IS NULL AND (
        NOT qty IS NULL
      ) AS _branch_quantity_coercible,
      SAFE_CAST(product_sku AS STRING) IS NULL AND (
        NOT product_sku IS NULL
      ) AS _branch_sku_coercible,
      CASE SAFE_CAST(state AS STRING)
        WHEN 'PROCESSING'
        THEN 'open'
        WHEN 'COMPLETE'
        THEN 'closed'
        ELSE SAFE_CAST(state AS STRING)
      END IS NULL
      AND (
        NOT state IS NULL
      ) AS _branch_status_coercible,
      NOT CASE SAFE_CAST(state AS STRING)
        WHEN 'PROCESSING'
        THEN 'open'
        WHEN 'COMPLETE'
        THEN 'closed'
        ELSE SAFE_CAST(state AS STRING)
      END IN ('closed', 'open') AS _branch_status_in_enum,
      'woo__order_lines' AS _source
    FROM bronze.woo__order_lines
  ) AS _extract
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY order_id, line_no
      ORDER BY placed_at DESC, line_no DESC, _source DESC, _source_row_id DESC
    ) = 1
)
SELECT
  *
FROM (
  SELECT
    COUNT(*) AS surviving_rows,
    SUM(
      CASE
        WHEN COALESCE(
          (
            _survivors._branch_gift_note_coercible
            OR _survivors._branch_order_id_coercible
            OR _survivors._branch_quantity_coercible
            OR _survivors._branch_sku_coercible
            OR _survivors._branch_status_coercible
            OR _survivors._branch_status_in_enum
          ),
          FALSE
        )
        THEN 1
        ELSE 0
      END
    ) AS diverted_rows,
    (
      SELECT
        COUNT(*)
      FROM bronze.shopify__order_lines
    ) + (
      SELECT
        COUNT(*)
      FROM bronze.woo__order_lines
    ) AS bronze_rows,
    (
      SELECT
        COUNT(*)
      FROM @this_model AS _entity
      WHERE
        (_entity._source, _entity._source_row_id) IN (
          SELECT
            _source,
            _source_row_id
          FROM _survivors
        )
    ) AS entity_rows
  FROM _survivors
) AS _conservation
WHERE
  entity_rows + diverted_rows <> surviving_rows
